-- Evidence (S6, docs/design/13-documents.md §8.1).
-- Generated by `prisma migrate dev --create-only` (the columns), then extended by hand with what
-- Prisma cannot express:
--
-- 1. document gets voided_at / void_reason (a void keeps the file and the links, with a reason) and
--    a free note; company gets the state of the 証憑の規程 (effective date, the two people
--    responsible, the version of the text).
-- 2. CHECK document_void_fields: a voided document has voided_at and void_reason, others have no
--    voided_at.
-- 3. ledger_document_guard (from *_ledger_guards) is replaced: on top of no DELETE and the fixed file
--    identity, a voided document cannot be restored, and voided_at / void_reason / supersedes_id
--    cannot be rewritten once set.

-- AlterTable
ALTER TABLE "company" ADD COLUMN     "records_policy_effective_on" DATE,
ADD COLUMN     "records_policy_manager" TEXT,
ADD COLUMN     "records_policy_operator" TEXT,
ADD COLUMN     "records_policy_version" TEXT;

-- AlterTable
ALTER TABLE "document" ADD COLUMN     "note" TEXT,
ADD COLUMN     "void_reason" TEXT,
ADD COLUMN     "voided_at" TIMESTAMPTZ(6);

-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "document"
  ADD CONSTRAINT "document_void_fields" CHECK (
    ("status" = 'voided') = ("voided_at" IS NOT NULL)
    AND ("status" <> 'voided' OR "void_reason" IS NOT NULL)
  );

-- ---------------------------------------------------------------------------
-- document: no DELETE (void instead); the stored file's identity never changes; a void is final
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION "ledger_document_guard"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ledger guard: document % cannot be deleted (void it instead)', OLD."id";
  END IF;
  IF NEW."storage_key" IS DISTINCT FROM OLD."storage_key"
     OR NEW."sha256" IS DISTINCT FROM OLD."sha256"
     OR NEW."byte_size" IS DISTINCT FROM OLD."byte_size"
     OR NEW."mime" IS DISTINCT FROM OLD."mime" THEN
    RAISE EXCEPTION 'ledger guard: storage_key, sha256, byte_size and mime of document % cannot change', OLD."id";
  END IF;
  IF OLD."status" = 'voided' AND NEW."status" <> 'voided' THEN
    RAISE EXCEPTION 'ledger guard: document % is voided and cannot be restored (replace it instead)', OLD."id";
  END IF;
  IF OLD."voided_at" IS NOT NULL AND NEW."voided_at" IS DISTINCT FROM OLD."voided_at" THEN
    RAISE EXCEPTION 'ledger guard: voided_at of document % is already set', OLD."id";
  END IF;
  IF OLD."void_reason" IS NOT NULL AND NEW."void_reason" IS DISTINCT FROM OLD."void_reason" THEN
    RAISE EXCEPTION 'ledger guard: void_reason of document % is already set', OLD."id";
  END IF;
  IF OLD."supersedes_id" IS NOT NULL AND NEW."supersedes_id" IS DISTINCT FROM OLD."supersedes_id" THEN
    RAISE EXCEPTION 'ledger guard: supersedes_id of document % is already set', OLD."id";
  END IF;
  RETURN NEW;
END;
$$;
